cat > /app/output/index.html <<'HTML'
<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>CreativeHub — Online Classes for Creatives</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

      :root {
        --bg: #f9f9fb;
        --surface: #ffffff;
        --ink: #131822;
        --muted: #647084;
        --line: #e7ecf3;
        --hero-bg: #0f172a;
        --hero-surface: rgba(255, 255, 255, 0.08);
        --hero-line: rgba(255, 255, 255, 0.15);
        --hero-text: #f8fbff;
        --accent-coral: #ff6b4a;
        --accent-green: #95ef3f;
        --accent-yellow: #ffd43b;
        --accent-blue: #2a7cff;
        --radius-xl: 28px;
        --radius-lg: 20px;
        --radius-md: 14px;
        --shadow: 0 16px 36px rgba(18, 28, 44, 0.08);
        --shadow-hero: 0 28px 60px rgba(0, 0, 0, 0.28);
      }

      * { box-sizing: border-box; }

      html, body {
        margin: 0;
        padding: 0;
        background: var(--bg);
        color: var(--ink);
        font-family: 'Plus Jakarta Sans', sans-serif;
      }

      a { color: inherit; text-decoration: none; }

      .container {
        width: min(1160px, 92vw);
        margin: 0 auto;
      }

      .pill, .btn, .tab, .faq-q, .teacher-btn, .course-card, .teacher-card, .testimonial, .team-card {
        transition: all 0.26s ease;
      }

      header {
        position: sticky;
        top: 0;
        z-index: 100;
        backdrop-filter: blur(12px);
        background: rgba(249, 249, 251, 0.85);
        border-bottom: 1px solid var(--line);
      }

      .nav {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 16px 0;
      }

      .brand {
        display: flex;
        align-items: center;
        gap: 10px;
        font-family: 'Space Grotesk', sans-serif;
        font-size: 1.3rem;
        font-weight: 700;
      }

      .brand-mark {
        width: 36px;
        height: 36px;
        border-radius: 12px;
        background: linear-gradient(145deg, var(--accent-coral), var(--accent-yellow));
        box-shadow: 0 10px 20px rgba(255, 107, 74, 0.35);
      }

      .nav-links {
        display: flex;
        align-items: center;
        gap: 18px;
        color: var(--muted);
        font-weight: 600;
      }

      .nav-links a:hover { color: var(--ink); }

      .nav-cta {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 11px 17px;
        border-radius: 12px;
        background: var(--ink);
        color: #fff;
        font-weight: 700;
      }

      .nav-cta:hover { transform: translateY(-1px); }

      .hero-wrap {
        padding: 28px 0 40px;
      }

      .hero {
        position: relative;
        overflow: hidden;
        border-radius: var(--radius-xl);
        background: radial-gradient(circle at 12% 18%, rgba(149, 239, 63, 0.18), transparent 40%),
          radial-gradient(circle at 88% 10%, rgba(255, 212, 59, 0.2), transparent 42%),
          linear-gradient(145deg, #0f172a, #111f3f 62%, #0e1a30);
        color: var(--hero-text);
        box-shadow: var(--shadow-hero);
        padding: clamp(28px, 5vw, 56px);
      }

      .hero-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr;
        gap: 32px;
      }

      .hero h1 {
        font-family: 'Space Grotesk', sans-serif;
        font-size: clamp(2.1rem, 5vw, 4.2rem);
        line-height: 0.98;
        margin: 10px 0 16px;
        letter-spacing: -0.03em;
      }

      .hero h1 .accent { color: var(--accent-yellow); }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        font-size: 0.84rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        padding: 8px 12px;
        border-radius: 999px;
        border: 1px solid var(--hero-line);
        background: var(--hero-surface);
      }

      .hero p {
        margin: 0;
        color: #ced7e8;
        font-size: 1.04rem;
        max-width: 58ch;
        line-height: 1.65;
      }

      .cta-panel {
        background: var(--hero-surface);
        border: 1px solid var(--hero-line);
        border-radius: var(--radius-lg);
        padding: 18px;
        margin-top: 26px;
      }

      .cta-title {
        margin: 0 0 14px;
        color: #dbe7ff;
        font-size: 0.92rem;
        font-weight: 700;
      }

      .btn-row {
        display: grid;
        grid-template-columns: 1fr;
        gap: 10px;
      }

      .btn {
        border: none;
        border-radius: 12px;
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        gap: 8px;
        font-family: inherit;
        font-weight: 700;
        padding: 14px 14px;
      }

      .btn-google {
        background: #fff;
        color: #1c2230;
      }

      .btn-email {
        background: linear-gradient(140deg, var(--accent-coral), #ff8a3d);
        color: #fff;
      }

      .btn:hover {
        transform: translateY(-2px);
        filter: brightness(1.03);
      }

      .hero-note {
        margin: 10px 0 0;
        color: #b8c4d9;
        font-size: 0.82rem;
      }

      .hero-visual {
        align-self: stretch;
        display: grid;
        gap: 14px;
      }

      .float-card {
        border-radius: 18px;
        background: rgba(255, 255, 255, 0.92);
        color: #101727;
        padding: 14px;
        box-shadow: 0 14px 30px rgba(0, 0, 0, 0.2);
      }

      .float-card strong {
        display: block;
        font-size: 1.05rem;
      }

      .float-mini {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 10px;
      }

      .mini-chip {
        border-radius: 12px;
        padding: 11px 8px;
        text-align: center;
        color: #fff;
        font-weight: 700;
      }

      .mini-chip:nth-child(1) { background: #2a7cff; }
      .mini-chip:nth-child(2) { background: #00b894; }
      .mini-chip:nth-child(3) { background: #ff6b4a; }

      .hero-pills {
        margin-top: 24px;
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
      }

      .pill {
        border: 1px solid var(--hero-line);
        color: #f4f8ff;
        background: rgba(255, 255, 255, 0.05);
        padding: 9px 14px;
        border-radius: 999px;
        font-size: 0.86rem;
        font-weight: 700;
      }

      .pill:hover {
        transform: translateY(-2px);
        border-color: rgba(255, 255, 255, 0.32);
      }

      .section {
        padding: 78px 0;
      }

      .section h2 {
        margin: 0;
        font-family: 'Space Grotesk', sans-serif;
        font-size: clamp(1.8rem, 3vw, 2.8rem);
        line-height: 1.1;
        letter-spacing: -0.02em;
      }

      .section-top {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 16px;
        margin-bottom: 24px;
      }

      .section-top p {
        color: var(--muted);
        max-width: 62ch;
        line-height: 1.65;
      }

      .feature-grid {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 16px;
      }

      .feature-card {
        background: var(--surface);
        border: 1px solid var(--line);
        border-radius: 18px;
        padding: 20px;
        box-shadow: var(--shadow);
      }

      .feature-card h3 { margin: 12px 0 8px; font-size: 1.12rem; }
      .feature-card p { margin: 0; color: var(--muted); line-height: 1.6; }

      .badge {
        width: 40px; height: 40px; border-radius: 12px;
        display: grid; place-items: center;
        font-weight: 800;
      }

      .stats-band {
        border-radius: var(--radius-xl);
        padding: 34px;
        background: linear-gradient(135deg, #fff8e9, #ffe9c4 52%, #ffe3c7);
        border: 1px solid #f9ddb4;
      }

      .stats-grid {
        display: grid;
        grid-template-columns: repeat(4, minmax(0, 1fr));
        gap: 14px;
      }

      .stat-card {
        background: rgba(255, 255, 255, 0.75);
        border: 1px solid rgba(255, 152, 0, 0.18);
        border-radius: 16px;
        padding: 18px;
      }

      .stat-num {
        font-family: 'Space Grotesk', sans-serif;
        font-size: clamp(1.5rem, 4vw, 2.45rem);
        margin: 0;
      }

      .stat-label { margin: 5px 0 0; color: #6f5f3f; font-weight: 600; }

      .tabs {
        display: flex;
        overflow-x: auto;
        gap: 8px;
        padding-bottom: 6px;
        margin-bottom: 18px;
      }

      .tab {
        border: 1px solid var(--line);
        border-radius: 999px;
        padding: 10px 14px;
        white-space: nowrap;
        font-weight: 700;
        color: #4f5d73;
        background: #fff;
        cursor: pointer;
      }

      .tab.active {
        border-color: #101b34;
        background: #101b34;
        color: #fff;
      }

      .course-grid {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 16px;
      }

      .course-card {
        background: #fff;
        border: 1px solid var(--line);
        border-radius: 18px;
        overflow: hidden;
        box-shadow: var(--shadow);
      }

      .course-card:hover { transform: translateY(-3px); }

      .thumb {
        aspect-ratio: 16 / 9;
        background-size: cover;
        background-position: center;
      }

      .course-body { padding: 14px; }
      .course-title { margin: 0 0 10px; font-size: 1rem; line-height: 1.35; }
      .meta { color: var(--muted); font-size: 0.9rem; }
      .meta strong { color: #2f3a4d; }

      .feed-grid, .testimonial-grid, .team-grid {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 16px;
      }

      .feed-card, .testimonial, .team-card {
        border-radius: 18px;
        border: 1px solid var(--line);
        background: #fff;
        padding: 18px;
        box-shadow: var(--shadow);
      }

      .teacher-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        margin-bottom: 12px;
      }

      .teacher-actions {
        display: flex;
        gap: 8px;
      }

      .teacher-btn {
        width: 38px;
        height: 38px;
        border-radius: 999px;
        border: 1px solid var(--line);
        background: #fff;
        cursor: pointer;
        font-weight: 700;
      }

      .teacher-btn:hover { background: #f2f6fc; }

      .teacher-scroll {
        display: grid;
        grid-auto-flow: column;
        grid-auto-columns: minmax(250px, 1fr);
        gap: 14px;
        overflow-x: auto;
        scroll-behavior: smooth;
        padding-bottom: 6px;
      }

      .teacher-card {
        background: #fff;
        border: 1px solid var(--line);
        border-radius: 18px;
        padding: 14px;
        box-shadow: var(--shadow);
      }

      .teacher-photo {
        aspect-ratio: 4/3;
        border-radius: 14px;
        margin-bottom: 12px;
        background-size: cover;
        background-position: center;
      }

      .teacher-role { color: var(--muted); margin: 5px 0 0; }

      .faq-wrap {
        background: #fff;
        border: 1px solid var(--line);
        border-radius: 18px;
        box-shadow: var(--shadow);
        overflow: hidden;
      }

      .faq-item + .faq-item { border-top: 1px solid var(--line); }

      .faq-q {
        width: 100%;
        border: none;
        background: #fff;
        text-align: left;
        display: flex;
        justify-content: space-between;
        gap: 12px;
        align-items: center;
        padding: 18px 20px;
        font-size: 1.02rem;
        font-weight: 700;
        cursor: pointer;
      }

      .faq-q:hover { background: #f7faff; }

      .faq-a {
        max-height: 0;
        overflow: hidden;
        padding: 0 20px;
        color: #516077;
        transition: max-height 0.25s ease, padding-bottom 0.25s ease;
      }

      .faq-item.active .faq-a {
        max-height: 180px;
        padding-bottom: 18px;
      }

      footer {
        margin-top: 70px;
        background: #0f172a;
        color: #d8e3fb;
      }

      .footer {
        padding: 40px 0;
        display: flex;
        flex-wrap: wrap;
        justify-content: space-between;
        gap: 16px;
      }

      .footer small { color: #94a8cf; }

      .reveal {
        opacity: 0;
        transform: translateY(14px);
        animation: rise 0.7s ease forwards;
      }

      .reveal:nth-child(2) { animation-delay: 0.08s; }
      .reveal:nth-child(3) { animation-delay: 0.14s; }

      @keyframes rise {
        to {
          opacity: 1;
          transform: translateY(0);
        }
      }

      @media (max-width: 980px) {
        .hero-grid, .feature-grid, .course-grid, .feed-grid, .testimonial-grid, .team-grid {
          grid-template-columns: 1fr 1fr;
        }
        .stats-grid { grid-template-columns: 1fr 1fr; }
      }

      @media (max-width: 720px) {
        .nav-links { display: none; }
        .hero-grid, .feature-grid, .course-grid, .feed-grid, .testimonial-grid, .team-grid {
          grid-template-columns: 1fr;
        }
        .stats-grid { grid-template-columns: 1fr; }
        .section { padding: 58px 0; }
        .hero { padding: 24px; }
      }
    </style>
  </head>
  <body>
    <header>
      <div class="container nav">
        <a class="brand" href="#"><span class="brand-mark"></span>CreativeHub</a>
        <nav class="nav-links">
          <a href="#courses">Browse</a>
          <a href="#">Sign In</a>
          <a class="nav-cta" href="#hero-signup">Sign Up</a>
        </nav>
      </div>
    </header>

    <main>
      <section class="hero-wrap" id="hero-signup">
        <div class="container hero">
          <div class="hero-grid">
            <div>
              <div class="eyebrow">✨ Learn with world-class creatives</div>
