            <article class="team-card"><h3>Agency Plan</h3><p>For high-velocity creative operations across clients.</p></article>
            <article class="team-card"><h3>Enterprise Plan</h3><p>For organizations scaling creative excellence globally.</p></article>
          </div>
        </div>
      </section>

      <section class="section" id="faq">
        <div class="container">
          <div class="section-top">
            <div>
              <h2>Frequently asked questions</h2>
            </div>
          </div>

          <div class="faq-wrap" id="faqWrap"></div>
        </div>
      </section>
    </main>

    <footer>
      <div class="container footer">
        <div class="brand"><span class="brand-mark"></span>CreativeHub</div>
        <small>© 2026 CreativeHub. Create every day.</small>
      </div>
    </footer>

    <script>
      const courses = [
        {
