          students: '17,980',
          duration: '3h 38m',
          category: 'Animation',
          thumb: 'linear-gradient(135deg,#84fab0,#8fd3f4)'
        }
      ];

      const categories = ['Featured', 'Music', 'Drawing & Painting', 'Marketing', 'Animation', 'Film & Video', 'UI/UX Design'];
      const tabsEl = document.getElementById('courseTabs');
      const courseGrid = document.getElementById('courseGrid');
      let activeTab = 'Featured';

      function renderTabs() {
        tabsEl.innerHTML = '';
        categories.forEach((cat) => {
          const button = document.createElement('button');
          button.className = `tab ${activeTab === cat ? 'active' : ''}`;
          button.textContent = cat;
          button.type = 'button';
          button.addEventListener('click', () => {
            activeTab = cat;
            renderTabs();
            renderCourses();
          });
          tabsEl.appendChild(button);
        });
      }

      function renderCourses() {
        const filtered = activeTab === 'Featured'
          ? courses.slice(0, 6)
          : courses.filter((course) => course.category === activeTab);

        courseGrid.innerHTML = filtered.map((course) => `
          <article class="course-card">
            <div class="thumb" style="background:${course.thumb}"></div>
            <div class="course-body">
              <h3 class="course-title">${course.title}</h3>
              <p class="meta"><strong>${course.instructor}</strong></p>
              <p class="meta">${course.students} students · ${course.duration}</p>
            </div>
          </article>
        `).join('');
      }

      const teachers = [
        { name: 'Amelia Ross', role: 'Illustrator', photo: 'linear-gradient(135deg,#ffecd2,#fcb69f)' },
        { name: 'Ravi Patel', role: 'Digital Designer', photo: 'linear-gradient(135deg,#a1ffce,#faffd1)' },
