        { name: 'Ella Monroe', role: 'Watercolor Artist', photo: 'linear-gradient(135deg,#89f7fe,#66a6ff)' },
        { name: 'Theo Lane', role: 'Motion Graphics Artist', photo: 'linear-gradient(135deg,#fccb90,#d57eeb)' }
      ];

      const teacherScroll = document.getElementById('teacherScroll');
      teacherScroll.innerHTML = teachers.map((teacher) => `
        <article class="teacher-card">
          <div class="teacher-photo" style="background:${teacher.photo}"></div>
          <h3 style="margin:0">${teacher.name}</h3>
          <p class="teacher-role">${teacher.role}</p>
        </article>
      `).join('');

      document.getElementById('teacherPrev').addEventListener('click', () => {
        teacherScroll.scrollBy({ left: -280, behavior: 'smooth' });
      });
      document.getElementById('teacherNext').addEventListener('click', () => {
        teacherScroll.scrollBy({ left: 280, behavior: 'smooth' });
      });

      const faqItems = [
        {
          q: 'What is CreativeHub?',
          a: 'CreativeHub is an online learning platform for creative skills, offering expert-led classes for artists, designers, musicians, and aspiring creators.'
        },
        {
          q: 'What is included in my membership?',
          a: 'Membership includes unlimited access to classes, project files, learning paths, community feedback, and new course releases each month.'
        },
        {
          q: 'What can I learn?',
          a: 'You can learn graphic design, illustration, animation, film and video, UI/UX, freelancing, content creation, music, and more.'
        },
        {
          q: 'What happens after my trial is over?',
          a: 'After the 30-day trial, your plan automatically continues at the selected membership rate unless you cancel before renewal.'
        },
        {
          q: 'Can I teach on the platform?',
          a: 'Yes. Experienced creatives can apply to become teachers and publish classes for our global learning community.'
        }
      ];

      const faqWrap = document.getElementById('faqWrap');
      faqWrap.innerHTML = faqItems.map((item, i) => `
        <article class="faq-item ${i === 0 ? 'active' : ''}">
          <button class="faq-q" type="button" aria-expanded="${i === 0 ? 'true' : 'false'}">
            <span>${item.q}</span>
            <span>${i === 0 ? '−' : '+'}</span>
          </button>
          <div class="faq-a"><p>${item.a}</p></div>
        </article>
      `).join('');

      faqWrap.addEventListener('click', (event) => {
        const btn = event.target.closest('.faq-q');
        if (!btn) return;

        const item = btn.parentElement;
        const isActive = item.classList.contains('active');

        [...faqWrap.querySelectorAll('.faq-item')].forEach((faq) => {
          faq.classList.remove('active');
          faq.querySelector('.faq-q').setAttribute('aria-expanded', 'false');
          faq.querySelector('.faq-q span:last-child').textContent = '+';
        });

        if (!isActive) {
          item.classList.add('active');
          btn.setAttribute('aria-expanded', 'true');
          btn.querySelector('span:last-child').textContent = '−';
        }
      });

      const signupMessage = (type) => {
        const text = type === 'google'
          ? 'Google sign-up flow would start here.'
          : 'Email sign-up form would open here.';
        alert(text);
      };

      document.getElementById('googleSignupBtn').addEventListener('click', () => signupMessage('google'));
      document.getElementById('emailSignupBtn').addEventListener('click', () => signupMessage('email'));

      renderTabs();
      renderCourses();
    </script>
